","ZAK","4129.5"],["VAR","ZAN","10088.4"],["VEN","VER","6465.2"],["VEN","VIS","3882.8"],["VEN","VLL","739.4"],["VEN","VLP","9691.1"],["VEN","WIL","5415.3"],["VEN","WLG","12285.9"],["VEN","XIA","13911.4"],["VEN","YEO","14716.2"],["VEN","ZAK","581.3"],["VEN","ZAN","9228.7"],["VER","VIS","5550.7"],["VER","VLL","5770.8"],["VER","VLP","9068"],["VER","WIL","1778.5"],["VER","WLG","11664.7"],["VER","XIA","14585.3"],["VER","YEO","15390"],["VER","ZAK","6054.6"],["VER","ZAN","9902.5"],["VIS","VLL","3170.6"],["VIS","VLP","9934.3"],["VIS","WIL","4895.7"],["VIS","WLG","12522.5"],["VIS","XIA","14124"],["VIS","YEO","14928.8"],["VIS","ZAK","3453.5"],["VIS","ZAN","9441.3"],["VLL","VLP","9023.1"],["VLL","WIL","4760.6"],["VLL","WLG","11617.7"],["VLL","XIA","13237.1"],["VLL","YEO","14041.9"],["VLL","ZAK","323.2"],["VLL","ZAN","8554.4"],["VLP","WIL","7497.1"],["VLP","WLG","5023.5"],["VLP","XIA","10044.1"],["VLP","YEO","9935.5"],["VLP","ZAK","9304.7"],["VLP","ZAN","7553.6"],["WIL","WLG","10012.1"],["WIL","XIA","12936.5"],["WIL","YEO","13741.3"],["WIL","ZAK","4991.2"],["WIL","ZAN","8246.7"],["WLG","XIA","5072.3"],["WLG","YEO","5256.7"],["WLG","ZAK","11925.8"],["WLG","ZAN","7167.8"],["XIA","YEO","804.8"],["XIA","ZAK","13605"],["XIA","ZAN","5680.5"],["YEO","ZAK","14472.5"],["YEO","ZAN","6492.9"],["ZAK","ZAN","8857.4"]]$seed$::jsonb;
  v_seen     text;
  v_n        int;
  v_def      text;
begin
  perform set_config('statement_timeout', '120s', true);
  perform set_config('lock_timeout', '5s', true);
  v_seen := (select md5(string_agg(a.code || '>' || e.key || '=' || e.value, ',' order by a.code collate "C", e.key collate "C"))
               from public.sea_reaches a join public.ports pa on pa.id = a.port_id and pa.kind = 'HARBOUR'
              cross join lateral jsonb_each_text(a.reaches) e
              where exists (select 1 from public.ports pb where pb.code = e.key and pb.kind = 'HARBOUR'));
  if v_seen is distinct from c_after then
    raise exception 'rollback-0491 refuses: the harbour pairs (digest %) are not 0491''s', v_seen;
  end if;
  if md5(replace(pg_get_functiondef('public.fleet_job_course(uuid,uuid,uuid)'::regprocedure), E'\r', '')) <> c_jc_after then
    raise exception 'rollback-0491 refuses: public.fleet_job_course is not 0491''s';
  end if;

  -- 1. THE FIGURES AS THEY WERE (both ways, one statement)
  update public.sea_reaches sr set reaches = sr.reaches || n.doc
    from (select d.code, jsonb_object_agg(d.k, d.v) doc
            from (select e->>0 code, e->>1 k, e->2 v from jsonb_array_elements(v_old) e
                  union all select e->>1, e->>0, e->2 from jsonb_array_elements(v_old) e) d
           group by d.code) n
   where n.code = sr.code;
  v_seen := (select md5(string_agg(a.code || '>' || e.key || '=' || e.value, ',' order by a.code collate "C", e.key collate "C"))
               from public.sea_reaches a join public.ports pa on pa.id = a.port_id and pa.kind = 'HARBOUR'
              cross join lateral jsonb_each_text(a.reaches) e
              where exists (select 1 from public.ports pb where pb.code = e.key and pb.kind = 'HARBOUR'));
  if v_seen is distinct from c_before then
    raise exception 'rollback-0491 FAIL: the harbour pairs are not the before figures (digest %)', v_seen;
  end if;
  if (select md5(string_agg(a.code || '>' || e.key || '=' || e.value, ',' order by a.code collate "C", e.key collate "C"))
        from public.sea_reaches a cross join lateral jsonb_each_text(a.reaches) e
       where not (exists (select 1 from public.ports pa where pa.id = a.port_id and pa.kind = 'HARBOUR')
                  and exists (select 1 from public.ports pb where pb.code = e.key and pb.kind = 'HARBOUR'))) is distinct from c_rest then
    raise exception 'rollback-0491 FAIL: a sea place''s figure moved';
  end if;
  if not exists (select 1 from public.sea_reach_matrix m, public.sea_reach_matrix_build() b
                  where m.id = 1 and m.ids = b.ids and m.codes = b.codes and m.nm = b.nm) then
    raise exception 'rollback-0491 FAIL: the matrix is not the one built from the table';
  end if;

  -- 2. THE PRICES FOLLOW (one statement)
  update public.port_goods pg set haul_nm = h.haul_nm, haul = h.haul
    from world.haul_rows() h
   where h.port_id = pg.port_id and h.good_id = pg.good_id and (pg.haul_nm, pg.haul) is distinct from (h.haul_nm, h.haul);
  get diagnostics v_n = row_count;
  v_seen := (select md5(string_agg(p.code || '/' || g.code || '=' || coalesce(pg.haul_nm::text, '-') || ':' || coalesce(pg.haul::text, '-'), ',' order by p.code collate "C", g.code collate "C"))
               from public.port_goods pg join public.ports p on p.id = pg.port_id join public.goods g on g.id = pg.good_id);
  if v_seen is distinct from c_haul then
    raise exception 'rollback-0491 FAIL: the hauls are not the before hauls (digest %)', v_seen;
  end if;

  -- 3. THE JOB'S COURSE, its pre-image (0491's two hunks reversed)
  v_def := replace(pg_get_functiondef('public.fleet_job_course(uuid,uuid,uuid)'::regprocedure), E'\r', '');
  v_def := replace(v_def, $h$  select coalesce(
    -- 0491 (sea_courses_enabled): FIRST the stored course between the two (public.sea_course), the course the board's miles are measured
    -- on (public.sea_reaches, 0491), so the trip a card quotes is the trip she sails; a lane, a coast course or her own voyage only where none
    case when public.sea_courses_on() then public.sea_course(p_from, p_to) end,
    (select k.course from public.npc_known_legs(p_from) k where k.to_port = p_to),$h$, $h$  select coalesce(
    (select k.course from public.npc_known_legs(p_from) k where k.to_port = p_to),$h$);
  v_def := replace(v_def, $h$      limit 1))$h$, $h$      limit 1),
    -- 0482 (sea_courses_enabled): else the stored course between the two (public.sea_course: the browser's own, roadstead to roadstead)
    case when public.sea_courses_on() then public.sea_course(p_from, p_to) end)$h$);
  execute v_def;
  if md5(replace(pg_get_functiondef('public.fleet_job_course(uuid,uuid,uuid)'::regprocedure), E'\r', '')) <> c_jc_pre then
    raise exception 'rollback-0491 FAIL: public.fleet_job_course is not its pre-image';
  end if;
  raise notice 'rollback-0491 ok: the figures, % market row(s) and the job''s course are as before 0491', v_n;
end
$r$;
